{"file_path":"src/format.js","content":"/**
 * Turns the segments produced by buildSegments into the text and exit
 * status for each of the three modes.
 */

function formatMerge(segments, includeBase) {
  const out = []
  let conflict = false
  for (const seg of segments) {
    if (seg.type === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      out.push(...seg.mineLines)
      if (includeBase) {
        out.push('||||||| base')
        out.push(...seg.baseLines)
      }
      out.push('=======')
      out.push(...seg.theirsLines)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...seg.lines)
    }
  }
  return { lines: out, conflict }
}

