  const out = []
  let conflict = false
  for (const seg of segments) {
    if (seg.type === 'conflict') {
      conflict = true
      out.push(`conflict mine=${seg.mineLines.length} base=${seg.baseLines.length} theirs=${seg.theirsLines.length}`)
    } else {
      out.push(`${seg.type} ${seg.lines.length}`)
    }
  }
  return { lines: out, conflict }
}

export function renderText(lines) {
  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}

export function render(mode, segments) {
  if (mode === 'merge') return formatMerge(segments, true)
  if (mode === 'merge2') return formatMerge(segments, false)
  return formatRegions(segments)
}
