{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { splitDocuments } from './parse.js'
import { buildSegments } from './regions.js'
import { render, renderText } from './format.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const text = await readStdin()
  let docs
  try {
    docs = splitDocuments(text)
  } catch (err) {
    fail(err.message)
    return
  }

  const [mine, base, theirs] = docs
  const segments = buildSegments(mine, base, theirs)
  const { lines, conflict } = render(mode, segments)
  process.exitCode = conflict ? 1 : 0
  process.stdout.write(renderText(lines))
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
"}

