{"file_path":"src/parse.js","content":"/**
 * Splits raw standard input text into the three documents (mine, base,
 * theirs). Throws with the exact wording the CLI needs to report when the
 * input does not hold exactly three parts separated by `%%%` lines.
 */
export function splitDocuments(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const docs = [[]]
  for (const line of rawLines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }

  if (docs.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }

  return docs
}
"}

{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence of two documents (whole lines, exact string
 * comparison), producing the list of changes describing every stretch the
 * subsequence does not cover: a run of base lines replaced by a run of the
 * other side's lines.
 */

// L[i][j] = length of the LCS of A[i:] and B[j:].
function lcsTable(A, B) {
  const m = A.length
  const n = B.length
  const L = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0))
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (A[i] === B[j]) {
        L[i][j] = 1 + L[i + 1][j + 1]
      } else {
        L[i][j] = Math.max(L[i + 1][j], L[i][j + 1])
      }
    }
  }
  return L
}

// Walks both documents from the start, matching equal current lines and
// otherwise advancing the side whose remaining subsequence is at least as
// long as the other's, preferring to advance the base on a tie.
function align(base, side) {
  const L = lcsTable(base, side)
  const m = base.length
  const n = side.length
  let i = 0
  let j = 0
  const matches = []
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (L[i + 1][j] >= L[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Returns the changes between base and side, each tagged with `side`
 * ('mine' or 'theirs') and carrying the base range it replaces and the
 * side's own range of replacement lines.
 */
export function computeChanges(base, side, sideName) {
  const matches = align(base, side)
  const changes = []
  let pi = 0
  let pj = 0
  for (const [i, j] of matches) {
    if (i > pi || j > pj) {
      changes.push({ baseStart: pi, baseEnd: i, start: pj, end: j, side: sideName })
    }
    pi = i + 1
    pj = j + 1
  }
  if (pi < base.length || pj < side.length) {
    changes.push({ baseStart: pi, baseEnd: base.length, start: pj, end: side.length, side: sideName })
  }
  return changes
}
"}

{"file_path":"src/regions.js","content":"/**
 * Groups the changes from both sides into regions and resolves each one
 * against the base and the two sides, following the merge specification.
 */
import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

function mergeOrder(changes) {
  return changes.slice().sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })
}

function buildRegions(combined) {
  const regions = []
  let idx = 0
  while (idx < combined.length) {
    let baseStart = combined[idx].baseStart
    let baseEnd = combined[idx].baseEnd
    const changes = [combined[idx]]
    idx++
    while (idx < combined.length && combined[idx].baseStart <= baseEnd) {
      baseEnd = Math.max(baseEnd, combined[idx].baseEnd)
      changes.push(combined[idx])
      idx++
    }
    regions.push({ baseStart, baseEnd, changes })
  }
  return regions
}

function sideLinesFor(changes, region, baseLines, doc) {
  if (changes.length === 0) return baseLines
  const sStart = Math.min(...changes.map(c => c.baseStart))
  const sEnd = Math.max(...changes.map(c => c.baseEnd))
  const back = sStart - region.baseStart
  const forward = region.baseEnd - sEnd
  const lineStart = Math.min(...changes.map(c => c.start)) - back
  const lineEnd = Math.max(...changes.map(c => c.end)) + forward
  return doc.slice(lineStart, lineEnd)
}

function resolveRegion(region, baseDoc, mineDoc, theirsDoc) {
  const baseLines = baseDoc.slice(region.baseStart, region.baseEnd)
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mineLines = sideLinesFor(mineChanges, region, baseLines, mineDoc)
  const theirsLines = sideLinesFor(theirsChanges, region, baseLines, theirsDoc)

  if (arraysEqual(mineLines, theirsLines)) {
    return { type: 'both', lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { type: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { type: 'mine', lines: mineLines }
  }
  return { type: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Returns the ordered list of segments covering the whole base document:
 * stable stretches untouched by any change, and resolved (or conflicting)
 * regions.
